async function forwardWithFailover(query: Buffer, upstreams: Endpoint[], opts: ForwardOptions): Promise<Buffer> {
  let lastErr: unknown;
  for (const upstream of upstreams) {
    try {
      return await forwardQuery(query, upstream, opts);
    } catch (e) {
      lastErr = e; // try the next upstream instead of failing immediately
    }
  }
  throw lastErr;
}

