// real, src/blocklist.ts add() (trimmed)
add(domain: string): void {
  const labels = labelsOf(domain);
  let node = this.root;
  for (let i = labels.length - 1; i >= 0; i--) {
    const label = labels[i]!;
    let next = node.children.get(label);
    if (!next) { next = { children: new Map(), blocked: false }; node.children.set(label, next); }
    node = next;
  }
  node.blocked = true;
}

// real, src/transport.ts forwardQuery() (full)
export async function forwardQuery(query: Buffer, to: Endpoint, opts: ForwardOptions): Promise<Buffer> {
  const udpReply = await queryUdp(to, query, opts.udpTimeoutMs, opts.onUdpBound);
  const header = decodeHeader(udpReply); // 12-byte peek, cheap; a bad reply here just throws WireError -> SERVFAIL
  if (!header.tc) return udpReply;
  return queryTcp(to, query, opts.tcpTimeoutMs);
}

// real, src/wire.ts Reader (trimmed)
class Reader {
  pos = 0;
  constructor(readonly buf: Buffer) {}
  need(n: number, what: string): void {
    if (this.pos + n > this.buf.length) throw new WireError(`truncated: ${what} needs ${n} byte(s) at offset ${this.pos}`);
  }
  u16(what: string): number {
    this.need(2, what);
    const v = this.buf.readUInt16BE(this.pos);
    this.pos += 2;
    return v;
  }
}

