function readSoaMinimum(r: Reader): number {
  r.name(); // MNAME, handles compression
  r.name(); // RNAME
  r.skip(4 + 4 + 4 + 4, "soa fixed fields"); // serial, refresh, retry, expire
  return r.u32("soa minimum"); // the negative-caching TTL, RFC 2308
}

