class SinkholeProxy {
  private readonly inFlight = new Map<string, Promise<Buffer>>();

  private async forwardCoalesced(key: string, query: Buffer): Promise<Buffer> {
    const existing = this.inFlight.get(key);
    if (existing) return existing; // join the in-flight request instead of starting a new one
    const promise = forwardQuery(query, this.upstream, { udpTimeoutMs: this.udpTimeoutMs, tcpTimeoutMs: this.tcpTimeoutMs })
      .finally(() => this.inFlight.delete(key)); // cleanup on success OR failure
    this.inFlight.set(key, promise);
    return promise;
  }
}

// illustrative note, not a code change -- the KEY insight:
// forwardQuery() and the successful-forward branch in proxy.ts's handle() both relay
// the EXACT raw buffer (query out, reply back). EDNS(0) OPT records in the additional
// section are never touched, so they pass through automatically today for ALLOWED queries.
// The remaining gap is only for proxy-BUILT responses (block/NXDOMAIN/FORMERR/SERVFAIL),
// which never echo an OPT record back even if the client sent one.

// illustrative extension, not in the repo today
private buildBlockResponse(base, q: Question): Buffer {
  if (this.mode === "nxdomain" || (q.type !== TYPE.A && q.type !== TYPE.AAAA)) {
    return encodeMessage(base(RCODE.NXDOMAIN, [q]), [q], []);
  }
  const rr = q.type === TYPE.A
    ? encodeARecord(q.name, this.sinkholeTtl, this.sinkholeAddress)
    : encodeAAAARecord(q.name, this.sinkholeTtl, this.sinkholeAddressV6); // new function, new option
  return encodeMessage(base(RCODE.NOERROR, [q]), [q], [rr]);
}

