  const before = proxy.stats.blocked + proxy.stats.cacheHits + proxy.stats.forwarded + proxy.stats.servfail;
  const start = Date.now();
  const result = await proxy.handle(buf);
  const after = proxy.stats.blocked + proxy.stats.cacheHits + proxy.stats.forwarded + proxy.stats.servfail;
  log({ at: start, latencyMs: Date.now() - start, answered: result !== undefined, countDelta: after - before });
  return result;
}

