/** Ratio of cache-eligible queries (non-blocked) that were served from cache. */
export function cacheHitRatio(stats: ProxyStats): number {
  const cacheEligible = stats.cacheHits + stats.forwarded + stats.servfail;
  if (cacheEligible === 0) return 0;
  return stats.cacheHits / cacheEligible;
}

