import { describe, it, expect } from "vitest";
import {
  ResponseCache, ManualClock, encodeMessage, encodeARecord, decodeResponse,
  type Header, type Question,
} from "../src/index.js";

describe("cached TTL counts down between two reads", () => {
  it("returns a lower TTL on the second get() after the clock advances", () => {
    const clock = new ManualClock(0);
    const cache = new ResponseCache({ clock });
    const header: Header = { id: 1, qr: true, opcode: 0, aa: false, tc: false, rd: true, ra: true, rcode: 0 };
    const q: Question = { name: "news.example.com", type: 1, class: 1 };
    const rr = encodeARecord(q.name, 300, "203.0.113.5");
    const buf = encodeMessage(header, [q], [rr]);
    const ttlOffsets = decodeResponse(buf).answers.map((a) => a.ttlOffset);

    cache.put("news.example.com", 1, buf, 300, ttlOffsets);

    const first = decodeResponse(cache.get("news.example.com", 1)!);
    expect(first.answers[0]!.ttl).toBe(300);

    clock.advance(10_000); // 10 seconds pass

    const second = decodeResponse(cache.get("news.example.com", 1)!);
    expect(second.answers[0]!.ttl).toBe(290);
  });
});

