import type { ProxyStats } from "../src/index.js";

/** Fraction of ALL handled queries that resulted in SERVFAIL. */
export function servfailRate(stats: ProxyStats): number {
  if (stats.total === 0) return 0;
  return stats.servfail / stats.total;
}

import { decodeHeader } from "../src/index.js";

/** Mirrors the id/QR check proxy.ts makes before trusting an upstream reply (see SinkholeProxy.handle). */
export function isValidUpstreamReply(queryBuf: Buffer, replyBuf: Buffer): boolean {
  let queryHeader, replyHeader;
  try {
    queryHeader = decodeHeader(queryBuf);
    replyHeader = decodeHeader(replyBuf);
  } catch {
    return false; // malformed either way -- never trust it
  }
  return replyHeader.qr && replyHeader.id === queryHeader.id;
}

// illustrative, generic utility -- not in the repo today, but designed to wrap forwardQuery()
export class InFlightCoalescer<T> {
  private readonly inFlight = new Map<string, Promise<T>>();

  /** Runs `fetcher` for `key` at most once per overlapping set of callers; late callers join the existing promise. */
  async run(key: string, fetcher: () => Promise<T>): Promise<T> {
    const existing = this.inFlight.get(key);
    if (existing) return existing;
    const promise = fetcher().finally(() => this.inFlight.delete(key)); // cleanup on success OR failure
    this.inFlight.set(key, promise);
    return promise;
  }

  get size(): number {
    return this.inFlight.size;
  }
}

